  8		private static final double FLOWER_CREATION_PROBABILITY = 0.07;
  9	
 10		private static final double MOUSE_CREATION_PROBABILITY = 0.07;
 11	
 12		private static final double DUCK_CREATION_PROBABILITY = 0.07;
 13	
 14		private static final double BIRD_CREATION_PROBABILITY = 0.07;
 15	
 16		private static final double WOLF_CREATION_PROBABILITY = 0.03;
 17	
 18		private static final double BEAR_CREATION_PROBABILITY = 0.03;
 19	
 20		private final RandomService random;
 21	
 22		private final List<AnimalSpawnRule> animalSpawnRules;
 23	
 24	
 25		public FieldPopulator() {
 26			this.random = RandomService.shared();
 27			this.animalSpawnRules = new ArrayList<>();
 28			registerAnimalSpawnRules();
 29		}
