 41		private Plant createPlant(FieldEnvironment field, Location location) {
 42			if (random.chance(FLOWER_CREATION_PROBABILITY)) {
 43				return new Flower(field, location);
 44			}
 45			return new Grass(field, location);
 46		}
 47	
 48	
 49		private Animal createAnimal(FieldEnvironment field, Location location) {
 50			return animalSpawnRules.stream()
 51					.filter(rule -> rule.shouldSpawn(random))
 52					.findFirst()
 53					.map(rule -> rule.createAnimal(field, location))
 54					.orElse(null);
 55		}
