 57	
 58		private void registerAnimalSpawnRules() {
 59			Stream.of(
 60					new AnimalSpawnRule(BIRD_CREATION_PROBABILITY, Bird::new),
 61					new AnimalSpawnRule(MOUSE_CREATION_PROBABILITY, Mouse::new),
 62					new AnimalSpawnRule(DUCK_CREATION_PROBABILITY, Duck::new),
 63					new AnimalSpawnRule(WOLF_CREATION_PROBABILITY, Wolf::new),
 64					new AnimalSpawnRule(BEAR_CREATION_PROBABILITY, Bear::new))
 65					.forEach(animalSpawnRules::add);
 66		}
