 68	
 69		private void populateLocation(FieldEnvironment field, Location location, List<Animal> animals, List<Plant> plants) {
 70			plants.add(createPlant(field, location));
 71	
 72			Animal animal = createAnimal(field, location);
 73			if (animal != null) {
 74				animals.add(animal);
 75			}
 76		}
