158				g.drawImage(tmpImage, 0, oldTop, null);
159	
160				yMax = (int) (yMax / SCALE_FACTOR);
161	
162				IntStream.range(0, lastVal.length)
163						.forEach(index -> lastVal[index] = oldTop + (int) (lastVal[index] * SCALE_FACTOR));
